apiVersion: apps/v1
kind: Deployment
metadata:
  name: vuoro-control-admin
  namespace: vuoro-system
  labels: {app.kubernetes.io/name: vuoro-control-admin}
spec:
  # One replica, Recreate: the admin plane is a single tunnel endpoint, and
  # two admin pods would only double the surface.
  replicas: 1
  strategy: {type: Recreate}
  selector:
    matchLabels: {app.kubernetes.io/name: vuoro-control-admin}
  template:
    metadata:
      labels: {app.kubernetes.io/name: vuoro-control-admin}
    spec:
      serviceAccountName: vuoro-control-admin
      automountServiceAccountToken: false
      imagePullSecrets: [{name: vuoro-ghcr-pull}]
      securityContext: {runAsNonRoot: true, runAsUser: 65532, runAsGroup: 65532, fsGroup: 65532, seccompProfile: {type: RuntimeDefault}}
      containers:
        - name: control-admin
          image: ghcr.io/bayleafwalker/vuoro-cloud@sha256:02b792fdf2324ad56ea3ae7a85e82c348b88ae00894bc2991c678f5b065875bf
          command: [vuoro-control-admin]
          # No hostPort: vuoro-system enforces the restricted Pod Security
          # level, which refuses any hostPort. Ingress is the NodePort Service
          # in service.yaml (10.44.0.1:30843, externalTrafficPolicy Local).
          # NetworkPolicy allow-admin-tunnel plus the app's TCP-peer check
          # admit only the operator's tunnel address.
          ports: [{name: admin, containerPort: 8443}]
          env:
            - {name: VUORO_CLOUD_SERVICE_ROLE, value: admin}
            - {name: VUORO_CLOUD_PACKAGE_MANIFEST_FILE, value: /app/config/compatibility.json}
            - {name: VUORO_CLOUD_ADMIN_LISTEN_PORT, value: "8443"}
            # The operator's tunnel peer only; never the node's 10.44.0.1.
            - {name: VUORO_CLOUD_ADMIN_SOURCE_CIDRS, value: 10.44.0.2/32}
            - {name: VUORO_CLOUD_ADMIN_WEBAUTHN_CONFIG_FILE, value: /var/run/vuoro/admin-webauthn/admin-webauthn.json}
            - {name: VUORO_CLOUD_ADMIN_SIGNING_KEY_FILE, value: /var/run/vuoro/admin-signing/admin-signing-key.pem}
            - {name: VUORO_CLOUD_ADMIN_VERIFICATION_KEY_FILE, value: /var/run/vuoro/admin-signing/admin-verification-key.pem}
            # The AS public key (public; ConfigMap vuoro-oauth-as-verification),
            # only so startup refuses an admin key equal to the AS key.
            - {name: VUORO_CLOUD_OAUTH_AS_PUBLIC_KEY_FILE, value: /var/run/vuoro/oauth-as-verification/oauth-as-public.pem}
            # Only the control runtime values this process needs, by key: not
            # the GitHub OAuth secret, the operator token hash or the gateway
            # key paths that envFrom would also bring in. The database as
            # vuoro_control_admin (DB role split, unit 1.5, G2c).
            - {name: VUORO_CLOUD_ENVIRONMENT_ID, valueFrom: {secretKeyRef: {name: vuoro-control-runtime, key: VUORO_CLOUD_ENVIRONMENT_ID}}}
            - {name: VUORO_CLOUD_DATABASE_URL, valueFrom: {secretKeyRef: {name: vuoro-control-admin-db, key: VUORO_CLOUD_DATABASE_URL}}}
            - {name: VUORO_CLOUD_TOKEN_PEPPER, valueFrom: {secretKeyRef: {name: vuoro-control-runtime, key: VUORO_CLOUD_TOKEN_PEPPER}}}
            # The admin resource derives from it: https://api.vuoro.cloud/control/admin.
            - {name: VUORO_CLOUD_PUBLIC_API_URL, valueFrom: {secretKeyRef: {name: vuoro-control-runtime, key: VUORO_CLOUD_PUBLIC_API_URL}}}
            - {name: VUORO_CLOUD_OAUTH_ISSUER, valueFrom: {secretKeyRef: {name: vuoro-control-runtime, key: VUORO_CLOUD_OAUTH_ISSUER, optional: true}}}
          # Probes come from the kubelet on the node, which is not an admin
          # source; /health/live and /health/ready alone skip the peer check
          # and return no data (src/vuoro_cloud/admin.py, HEALTH_PATHS).
          readinessProbe: {httpGet: {path: /health/ready, port: admin}}
          livenessProbe: {httpGet: {path: /health/live, port: admin}}
          resources:
            requests: {cpu: 50m, memory: 128Mi}
            limits: {cpu: 250m, memory: 256Mi}
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities: {drop: [ALL]}
          volumeMounts:
            - {name: compatibility, mountPath: /app/config, readOnly: true}
            - {name: admin-webauthn, mountPath: /var/run/vuoro/admin-webauthn, readOnly: true}
            - {name: admin-signing-key, mountPath: /var/run/vuoro/admin-signing, readOnly: true}
            - {name: oauth-as-verification-key, mountPath: /var/run/vuoro/oauth-as-verification, readOnly: true}
      volumes:
        - {name: compatibility, configMap: {name: vuoro-compatibility}}
        - {name: admin-webauthn, configMap: {name: vuoro-admin-webauthn}}
        # Created by the operator (docs/runbooks/admin-plane.md, "Admin token
        # key"); mounted by this Deployment alone, never by control or the
        # gateway. Until it exists the pod does not start: fail closed.
        - {name: admin-signing-key, secret: {secretName: vuoro-admin-signing-key}}
        - {name: oauth-as-verification-key, configMap: {name: vuoro-oauth-as-verification}}
---
apiVersion: v1
kind: ServiceAccount
metadata: {name: vuoro-control-admin, namespace: vuoro-system}
automountServiceAccountToken: false
